form.script:
                        document.addEventListener('DOMContentLoaded', function () {
                        console.log(document.getElementById('alert_type'));
                        console.log(document.getElementById('alert_name'));

                        const alertType = document.getElementById('alert_type');
                        const alertName = document.getElementById('alert_name');
                        if (alertType && alertName){
                                alertType.addEventListener('change', function () {
            alertName.value =
                this.options[this.selectedIndex].text;
        });
    }

});

const selectedTowers = {};

document.getElementById('tower_dropdown').addEventListener('change', function () {
const id = this.value;
const text = this.options[this.selectedIndex].text;

if (!id || selectedTowers[id]) {
this.value = "";
return;
}

// Store selection
selectedTowers[id] = text;

// Add hidden input
const input = document.createElement('input');
input.type = 'hidden';
input.name = 'tower_id';
input.value = id;
input.id = 'tower_input_' + id;
document.getElementById('tower_hidden_inputs').appendChild(input);

// Add tag
const tag = document.createElement('span');
tag.className = 'badge bg-primary d-flex align-items-center gap-1';
tag.id = 'tower_tag_' + id;
const removeBtn = document.createElement('span');
removeBtn.innerHTML = '✕';
removeBtn.style.cursor = 'pointer';

removeBtn.addEventListener('click',function(){
removeTower(id);})

tag.appendChild(document.createTextNode(text));
tag.appendChild(removeBtn);


document.getElementById('tower_tags').appendChild(tag);

// Reset dropdown
this.value = "";
});






function removeTower(id) {
console.log('Removing:', id);
console.log(document.getElementById('tower_input_ '+ id ));

console.log(document.getElementById('tower_tag_' + id));
delete selectedTowers[id];


const input = document.getElementById('tower_input_' + id);
const tag = document.getElementById('tower_tag_' + id);

if (input) input.remove();
if (tag) tag.remove();
}

